"""Writes `transcript_cases.rs` here (included by `tests/transcripts.rs`): one Rust test per recorded
transcript (see record_transcripts.py), grouped by the Python test file, named after the Python test
without `test_`.

    python3 panel/crates/protocols/tests/fixtures/gen_transcript_tests.py
"""
from __future__ import annotations

import json
import re
from pathlib import Path

HERE = Path(__file__).resolve().parent


def rust_name(test: str) -> str:
    name = test.removeprefix("test_")
    name = re.sub(r"[^0-9A-Za-z]+", "_", name).strip("_").lower()
    return name


def main() -> None:
    transcripts = json.loads((HERE / "transcripts.json").read_text())
    modules: dict[str, list[tuple[str, str]]] = {}
    for transcript in transcripts:
        if not transcript["passed"] or not transcript["calls"]:
            continue
        path, test = transcript["test"].split("::", 1)
        module = Path(path).stem.removeprefix("test_")
        modules.setdefault(module, []).append((rust_name(test), transcript["test"]))
    lines = ["// Generated by tests/fixtures/gen_transcript_tests.py from transcripts.json: do not edit.", ""]
    for module, cases in modules.items():
        lines.append(f"mod {module} {{")
        lines.append("    use super::replay;")
        for name, nodeid in cases:
            lines += ["", "    #[tokio::test]", f"    async fn {name}() {{", f"        replay({json.dumps(nodeid)}).await;",
                      "    }"]
        lines += ["}", ""]
    (HERE / "transcript_cases.rs").write_text("\n".join(lines))


if __name__ == "__main__":
    main()
